checker.setup:
from types import SimpleNamespace

class StubClient:
    def __init__(self):
        self.aliases = {"champion": "3"}
        self.runs = {"3": "run-a", "4": "run-b", "5": "run-c"}
        self.scores = {"run-a": 0.80, "run-b": 0.805, "run-c": 0.83}
    def get_model_version_by_alias(self, name, alias):
        v = self.aliases[alias]
        return SimpleNamespace(version=v, run_id=self.runs[v])
    def get_model_version(self, name, version):
        return SimpleNamespace(version=version, run_id=self.runs[version])
    def get_run(self, run_id):
        return SimpleNamespace(data=SimpleNamespace(metrics={"auc": self.scores[run_id]}))
    def set_registered_model_alias(self, name, alias, version):
        self.aliases[alias] = version

tests.code:
c = StubClient()
assert promote_if_better(c, "churn_model", "5", "auc", 0.01) is True
assert c.aliases == {"champion": "5", "previous_champion": "3"}

c = StubClient()
assert promote_if_better(c, "churn_model", "4", "auc", 0.01) is False
assert c.aliases == {"champion": "3"}

